// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

import {IDeploymentBlock} from "./interfaces/decent/IDeploymentBlock.sol";
import {
    Initializable
} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/**
 * @title DeploymentBlockInitializable
 * @author Decent Labs
 * @notice Abstract implementation of deployment block tracking for initializable contracts
 * @dev This abstract contract implements IDeploymentBlock, providing a standard
 * way to record when initializable contracts are deployed.
 *
 * Implementation details:
 * - Uses EIP-7201 namespaced storage pattern for upgradeability
 * - Records block number during initialization
 * - Deployment block is immutable once set
 * - Designed for UUPS and transparent proxy patterns
 * - Must be inherited by initializable contracts
 *
 * Usage:
 * - Call __DeploymentBlockInitializable_init() in the inheriting contract's initializer
 * - The deployment block is automatically set to the current block
 * - Query deploymentBlock() to get the recorded value
 *
 * Security considerations:
 * - Can only be set once during initialization
 * - Prevents reinitialization attacks
 * - Provides reliable deployment block number
 *
 * @custom:security-contact security@decentlabs.io
 */
abstract contract DeploymentBlockInitializable is
    Initializable,
    IDeploymentBlock
{
    // ======================================================================
    // STATE VARIABLES
    // ======================================================================

    /**
     * @notice Main storage struct for DeploymentBlockInitializable following EIP-7201
     * @dev Stores the block number when the contract was deployed
     * @custom:storage-location erc7201:Decent.DeploymentBlockInitializable.main
     */
    struct DeploymentBlockInitializableStorage {
        /** @notice The block number when this contract was deployed */
        uint256 deploymentBlock;
    }

    /**
     * @dev Storage slot for DeploymentBlockInitializableStorage calculated using EIP-7201 formula:
     * keccak256(abi.encode(uint256(keccak256("Decent.DeploymentBlockInitializable.main")) - 1)) & ~bytes32(uint256(0xff))
     */
    bytes32 internal constant DEPLOYMENT_BLOCK_INITIALIZABLE_STORAGE_LOCATION =
        0x8a73f35b9df1b6f9967ddd5a4ec6ec57f8bdee83334d4552823c6e36f981ab00;

    /**
     * @dev Returns the storage struct for DeploymentBlockInitializable
     * Following the EIP-7201 namespaced storage pattern to avoid storage collisions
     * @return $ The storage struct for DeploymentBlockInitializable
     */
    function _getDeploymentBlockInitializableStorage()
        internal
        pure
        returns (DeploymentBlockInitializableStorage storage $)
    {
        // solhint-disable-next-line no-inline-assembly
        assembly {
            $.slot := DEPLOYMENT_BLOCK_INITIALIZABLE_STORAGE_LOCATION
        }
    }

    // ======================================================================
    // CONSTRUCTOR & INITIALIZERS
    // ======================================================================

    /**
     * @notice Initializes the deployment block tracking
     * @dev Must be called by inheriting contracts in their initializer.
     * Records the current block number as the deployment block.
     * Can only be called once due to the check for existing value.
     * @custom:throws DeploymentBlockAlreadySet if already initialized
     */
    function __DeploymentBlockInitializable_init() internal onlyInitializing {
        // solhint-disable-previous-line func-name-mixedcase
        DeploymentBlockInitializableStorage
            storage $ = _getDeploymentBlockInitializableStorage();
        if ($.deploymentBlock != 0) {
            revert DeploymentBlockAlreadySet();
        }

        $.deploymentBlock = block.number;
    }

    // ======================================================================
    // IDeploymentBlock
    // ======================================================================

    // --- View Functions ---

    /**
     * @inheritdoc IDeploymentBlock
     */
    function deploymentBlock() public view virtual override returns (uint256) {
        DeploymentBlockInitializableStorage
            storage $ = _getDeploymentBlockInitializableStorage();
        return $.deploymentBlock;
    }
}

contracts/DeploymentBlockNonInitializabl.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

import {IDeploymentBlock} from "./interfaces/decent/IDeploymentBlock.sol";

/**
 * @title DeploymentBlockNonInitializable
 * @author Decent Labs
 * @notice Abstract implementation of deployment block tracking for non-initializable contracts
 * @dev This abstract contract implements IDeploymentBlock, providing a standard
 * way to record when non-initializable contracts are deployed.
 *
 * Implementation details:
 * - Uses EIP-7201 namespaced storage pattern for consistency
 * - Records block number in constructor
 * - Deployment block is immutable once set
 * - Designed for singleton and utility contracts
 * - Must be inherited by non-initializable contracts
 *
 * Usage:
 * - Simply inherit this contract - no initialization needed
 * - The deployment block number is automatically set in the constructor
 * - Query deploymentBlock() to get the recorded value
 *
 * Differences from DeploymentBlockInitializable:
 * - No initializer pattern - uses constructor
 * - No reinitialization concerns
 * - Simpler implementation for non-initializable contracts
 *
 * @custom:security-contact security@decentlabs.io
 */
abstract contract DeploymentBlockNonInitializable is IDeploymentBlock {
    // ======================================================================
    // STATE VARIABLES
    // ======================================================================

    uint256 private immutable _deploymentBlock;

    // ======================================================================
    // CONSTRUCTOR
    // ======================================================================

    /**
     * @notice Records the deployment block during contract construction
     * @dev Automatically captures the current block number when the contract
     * is deployed. This happens once and the value is immutable.
     */
    constructor() {
        _deploymentBlock = block.number;
    }

    // ======================================================================
    // IDeploymentBlock
    // ======================================================================

    // --- View Functions ---

    /**
     * @inheritdoc IDeploymentBlock
     */
    function deploymentBlock() public view virtual override returns (uint256) {
        return _deploymentBlock;
    }
}

contracts/InitializerEventEmitter.sol.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

import {
    Initializable
} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/**
 * @title InitializerEventEmitter
 * @author Decent Labs
 * @notice Abstract contract for emitting initialization data during contract deployment
 * @dev This abstract contract provides a standardized way to emit initialization
 * data for initializable contracts in the Decent ecosystem.
 *
 * Implementation details:
 * - Designed to be inherited by upgradeable contracts
 * - Emits raw initialization data for transparency and auditability
 * - Minimal gas overhead with single event emission
 * - Follows OpenZeppelin's initializer pattern
 * - Uses `onlyInitializing` modifier for security
 *
 * Usage:
 * - Inherit this contract in your upgradeable contract
 * - Call `__InitializerEventEmitter_init()` in your initializer function
 * - Pass the encoded initialization parameters as bytes
 *
 * Example:
 * ```solidity
 * contract MyContract is InitializerEventEmitter, OtherContracts {
 *     function initialize(address owner_, uint256 value_) public initializer {
 *         bytes memory initData = abi.encode(owner_, value_);
 *         __InitializerEventEmitter_init(initData);
 *         // ... rest of initialization
 *     }
 * }
 * ```
 *
 * @custom:security-contact security@decentlabs.io
 */
abstract contract InitializerEventEmitter is Initializable {
    // ======================================================================
    // ERRORS
    // ======================================================================

    /**
     * @notice Thrown when attempting to initialize after already initialized
     * @dev Prevents reinitialization attacks on upgradeable contracts
     */
    error InitializeDataAlreadyEmitted();

    // ======================================================================
    // EVENTS
    // ======================================================================

    /**
     * @notice Emitted when a contract is initialized with data
     * @dev This event provides transparency for all initialization parameters
     * @param initData The raw initialization data passed to the contract
     */
    event InitializeData(bytes initData);

    // ======================================================================
    // STATE VARIABLES
    // ======================================================================

    /**
     * @notice Storage struct for InitializerEventEmitter following EIP-7201
     * @dev Tracks whether initialization data has been emitted
     * @custom:storage-location erc7201:Decent.InitializerEventEmitter.main
     */
    struct InitializerEventEmitterStorage {
        /** @notice Whether the initialization data has been emitted */
        bool initialized;
    }

    /**
     * @dev Storage slot for InitializerEventEmitterStorage calculated using EIP-7201 formula:
     * keccak256(abi.encode(uint256(keccak256("Decent.InitializerEventEmitter.main")) - 1)) & ~bytes32(uint256(0xff))
     */
    bytes32 internal constant INITIALIZER_EVENT_EMITTER_STORAGE_LOCATION =
        0xf7464a9b8e299d18ec8976df251e878e5204887b642c36b9e3e606b459323300;

    /**
     * @dev Returns the storage struct for InitializerEventEmitter
     * Following the EIP-7201 namespaced storage pattern to avoid storage collisions
     * @return $ The storage struct for InitializerEventEmitter
     */
    function _getInitializerEventEmitterStorage()
        internal
        pure
        returns (InitializerEventEmitterStorage storage $)
    {
        // solhint-disable-next-line no-inline-assembly
        assembly {
            $.slot := INITIALIZER_EVENT_EMITTER_STORAGE_LOCATION
        }
    }

    // ======================================================================
    // INITIALIZERS
    // ======================================================================

    /**
     * @notice Initializes the event emitter and emits the initialization data
     * @dev Must be called by inheriting contracts in their initializer function.
     * Can only be called once - subsequent calls will revert.
     * @param initData The initialization data to emit
     * @custom:throws InitializeDataAlreadyEmitted if already initialized
     */
    function __InitializerEventEmitter_init(
        // solhint-disable-previous-line func-name-mixedcase
        bytes memory initData
    ) internal onlyInitializing {
        InitializerEventEmitterStorage
            storage $ = _getInitializerEventEmitterStorage();

        if ($.initialized) {
            revert InitializeDataAlreadyEmitted();
        }

        $.initialized = true;
        emit InitializeData(initData);
    }
}

contracts/interfaces/decent/deployables/.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

/**
 * @title ICountersignV1
 * @notice Multi-party agreement system with KYC verification and weighted signatures
 * @dev This contract facilitates the creation of agreements that require multiple parties
 * to sign and execute transactions. It supports KYC verification through an external
 * verifier contract, weighted signing, and conditional transaction execution.
 *
 * Key features:
 * - Signers with configurable weights and required status
 * - KYC verification for all signers through external verifier
 * - Two-phase process: signing period followed by execution period
 * - Pre-execution transactions that run before signer transactions
 * - Per-signer transaction bundles executed upon signature
 * - Minimum weight threshold for agreement validity
 *
 * Workflow:
 * 1. Contract is initialized with signers, deadlines, and transaction details
 * 2. Signers call sign() during the signing period (KYC verification required)
 * 3. After signing deadline, if minimum weight is met, execute() can be called
 * 4. Execute runs pre-execution transactions, then all signer transactions
 *
 * Use cases:
 * - Legal agreements requiring multiple party consent
 * - Investment rounds with multiple investors
 * - Multi-party business agreements with conditional execution
 * - DAO formation with initial member agreements
 */
interface ICountersignV1 {
    // --- Errors ---

    /** @notice Thrown when a non-signer attempts to sign */
    error InvalidSigner();

    /** @notice Thrown when attempting to sign after the signing deadline */
    error SigningDeadlineElapsed();

    /** @notice Thrown when attempting to execute after the execution deadline */
    error ExecutionDeadlineElapsed();

    /** @notice Thrown when a signer attempts to sign more than once */
    error SignerAlreadySigned();

    /** @notice Thrown when executing without all required signers having signed */
    error RequiredSignerNotSigned(address signer);

    /** @notice Thrown when a required signer's transaction bundle fails during execution */
    error RequiredSignerTxFailed(address signer);

    /** @notice Thrown when the total weight of signatures doesn't meet the minimum threshold */
    error MinimumWeightNotMet();

    /** @notice Thrown when attempting to execute before the signing deadline has passed */
    error SigningDeadlineNotElapsed();

    /** @notice Thrown when pre-execution transactions fail during execution */
    error PreExecutionTxFailed();

    // --- Structs ---

    /**
     * @notice Initialization parameters for a signer
     * @param account The address of the signer
     * @param required Whether this signer must sign for the agreement to be valid
     * @param weight The signing weight of this signer (contributes to minimum threshold)
     * @param transactions Encoded transaction data to execute when this signer signs
     */
    struct SignerInitialization {
        address account;
        bool required;
        uint256 weight;
        bytes transactions;
    }

    /**
     * @notice Complete state information for a signer
     * @param isSigner Whether this address is a valid signer
     * @param required Whether this signer must sign for execution to proceed
     * @param signed Whether this signer has signed the agreement
     * @param executed Whether this signer's transactions have been executed
     * @param signedTimestamp The timestamp when this signer signed (0 if not signed)
     * @param weight The signing weight of this signer
     * @param transactions The encoded transactions to execute for this signer
     */
    struct Signer {
        bool isSigner;
        bool required;
        bool signed;
        bool executed;
        uint48 signedTimestamp;
        uint256 weight;
        bytes transactions;
    }

    // --- Events ---

    /**
     * @notice Emitted when a signer successfully signs the agreement
     * @param signer The address of the signer
     */
    event Signed(address indexed signer);

    /**
     * @notice Emitted when a signer's transaction bundle is successfully executed
     * @param signer The address of the signer whose transactions were executed
     */
    event SignerTxExecuted(address indexed signer);

    /**
     * @notice Emitted when a signer's transaction bundle fails during execution
     * @dev Non-required signer transaction failures are logged but don't revert execution
     * @param signer The address of the signer whose transactions failed
     */
    event SignerTxFailed(address indexed signer);

    // --- Initializer Functions ---

    /**
     * @notice Initializes the countersign agreement with all parameters
     * @dev Can only be called once during deployment. Sets up the complete agreement structure.
     * @param owner_ The address with owner privileges (can be a Safe or EOA)
     * @param agreementUri_ IPFS URI or other link to the agreement document
     * @param verificationContract_ Address of the KYC verifier contract
     * @param signingDeadline_ Timestamp after which no more signatures are accepted
     * @param executionDeadline_ Timestamp after which execution is no longer allowed
     * @param multisend_ Address of the Gnosis MultiSend contract for batch transactions
     * @param minWeight_ Minimum total weight required from signers for valid execution
     * @param preExecutionTransactions_ Encoded transactions to execute before signer transactions
     * @param signerInitializations_ Array of signer configurations including their transactions
     */
    function initialize(
        address owner_,
        string memory agreementUri_,
        address verificationContract_,
        uint48 signingDeadline_,
        uint48 executionDeadline_,
        address multisend_,
        uint256 minWeight_,
        bytes memory preExecutionTransactions_,
        SignerInitialization[] memory signerInitializations_
    ) external;

    // --- View Functions ---

    /**
     * @notice Returns whether the initial execution has been completed
     * @dev True after execute() has been successfully called
     * @return isComplete Whether execution is complete
     */
    function initialExecutionComplete() external view returns (bool isComplete);

    /**
     * @notice Returns the URI of the agreement document
     * @dev Typically an IPFS hash or URL to the legal agreement
     * @return agreementUri The agreement document URI
     */
    function agreementUri() external view returns (string memory agreementUri);

    /**
     * @notice Returns the address of the KYC verifier contract
     * @dev This contract validates signer signatures against KYC requirements
     * @return kycVerifier The KYC verifier contract address
     */
    function kycVerifier() external view returns (address kycVerifier);

    /**
     * @notice Returns the deadline for signers to sign the agreement
     * @dev After this timestamp, sign() will revert
     * @return signingDeadline The signing deadline timestamp
     */
    function signingDeadline() external view returns (uint48 signingDeadline);

    /**
     * @notice Returns the deadline for executing the agreement
     * @dev After this timestamp, execute() will revert
     * @return executionDeadline The execution deadline timestamp
     */
    function executionDeadline()
        external
        view
        returns (uint48 executionDeadline);

    /**
     * @notice Returns the address of the MultiSend contract used for batch execution
     * @dev Used to execute multiple transactions in a single call
     * @return multisend The MultiSend contract address
     */
    function multisend() external view returns (address multisend);

    /**
     * @notice Returns the minimum weight required for agreement execution
     * @dev Sum of signer weights must meet or exceed this threshold
     * @return minWeight The minimum weight threshold
     */
    function minWeight() external view returns (uint256 minWeight);

    /**
     * @notice Returns an array of all signer addresses
     * @dev Includes both required and optional signers
     * @return signerAddresses Array of signer addresses
     */
    function signerAddresses()
        external
        view
        returns (address[] memory signerAddresses);

    /**
     * @notice Returns complete data for a specific signer
     * @param signer_ The address to query
     * @return isSigner Whether this address is a valid signer
     * @return required Whether this signer is required for execution
     * @return signed Whether this signer has signed
     * @return executed Whether this signer's transactions have been executed
     * @return signedTimestamp When this signer signed (0 if not signed)
     * @return weight This signer's signing weight
     * @return transactions This signer's transaction data
     */
    function signerData(
        address signer_
    )
        external
        view
        returns (
            bool isSigner,
            bool required,
            bool signed,
            bool executed,
            uint48 signedTimestamp,
            uint256 weight,
            bytes memory transactions
        );

    /**
     * @notice Returns the pre-execution transaction data
     * @dev These transactions are executed before any signer transactions
     * @return preExecutionTransactions Encoded transaction data for pre-execution
     */
    function preExecutionTransactions()
        external
        view
        returns (bytes memory preExecutionTransactions);

    // --- State-Changing Functions ---

    /**
     * @notice Allows a valid signer to sign the agreement
     * @dev Caller must be in the signers list and pass KYC verification.
     * Can only be called during the signing period (before signingDeadline).
     * Each signer can only sign once.
     * @param verifyingSignature_ The verifier signature attesting to KYC status
     * @param signatureExpiration_ The expiration timestamp of the signature
     * @custom:throws InvalidSigner if caller is not a valid signer
     * @custom:throws SigningDeadlineElapsed if past the signing deadline
     * @custom:throws SignerAlreadySigned if caller has already signed
     * @custom:throws KYCVerificationFailed if KYC verification fails
     * @custom:emits Signed when signature is recorded
     */
    function sign(
        bytes calldata verifyingSignature_,
        uint48 signatureExpiration_
    ) external;

    /**
     * @notice Executes the agreement after signing period ends
     * @dev Can be called by anyone after signing deadline has passed.
     * Validates that all required signers have signed and minimum weight is met.
     * Executes pre-execution transactions first, then all signer transactions.
     * Can only be executed once and must be before execution deadline.
     * @custom:throws SigningDeadlineNotElapsed if called during signing period
     * @custom:throws ExecutionDeadlineElapsed if past execution deadline
     * @custom:throws RequiredSignerNotSigned if a required signer hasn't signed
     * @custom:throws MinimumWeightNotMet if total weight is below threshold
     * @custom:throws PreExecutionTxFailed if pre-execution transactions fail
     * @custom:throws RequiredSignerTxFailed if a required signer's transactions fail
     * @custom:emits SignerTxExecuted for each successful signer transaction bundle
     * @custom:emits SignerTxFailed for each failed non-required signer transaction bundle
     */
    function execute() external;
}

// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

/**
 * @title IPublicSaleV1
 * @notice Interface for a public token sale contract with KYC verification
 * @dev Implements a time-based token sale with configurable parameters including:
 * - Sale duration with start and end timestamps
 * - Minimum and maximum commitment amounts per user
 * - Minimum and maximum total commitment amounts for the sale
 * - KYC verification requirement
 * - Configurable fees for decreasing commitments and protocol
 * - Support for both native assets (ETH) and ERC20 tokens as payment
 */
interface IPublicSaleV1 {
    // --- Errors ---

    /**
     * @notice Thrown when the sale start timestamp is in the past during initialization
     */
    error InvalidSaleStartTimestamp();

    /**
     * @notice Thrown when the sale end timestamp is not after the start timestamp
     */
    error InvalidSaleTimestamps();

    /**
     * @notice Thrown when minimum commitment exceeds maximum commitment
     */
    error InvalidCommitmentAmounts();

    /**
     * @notice Thrown when minimum total commitment exceeds maximum total commitment
     */
    error InvalidTotalCommitmentAmounts();

    /**
     * @notice Thrown when a token or native asset transfer fails
     */
    error TransferFailed();

    /**
     * @notice Thrown when attempting to commit during inactive sale period
     */
    error SaleNotActive();

    /**
     * @notice Thrown when attempting to settle before the sale has ended
     */
    error SaleNotEnded();

    /**
     * @notice Thrown when attempting to settle an already settled account
     */
    error AlreadySettled();

    /**
     * @notice Thrown when decrease amount exceeds user's current commitment
     */
    error DecreaseAmountExceedsCommitment();

    /**
     * @notice Thrown when remaining commitment would be below minimum (unless going to zero)
     */
    error MinimumCommitment();

    /**
     * @notice Thrown when commitment would exceed maximum per user
     */
    error MaximumCommitment();

    /**
     * @notice Thrown when total commitments would exceed maximum for the sale
     */
    error MaximumTotalCommitment();

    /**
     * @notice Thrown when an amount parameter is zero
     */
    error ZeroAmount();

    /**
     * @notice Thrown when decrease commitment fee exceeds 100% (PRECISION)
     */
    error InvalidDecreaseCommitmentFee();

    /**
     * @notice Thrown when user attempts to settle with zero commitment
     */
    error ZeroCommitment();

    /**
     * @notice Thrown when protocol fee exceeds 100% (PRECISION)
     */
    error InvalidProtocolFee();

    /**
     * @notice Thrown when using wrong commitment function for the token type
     */
    error InvalidCommitmentToken();

    // --- Structs ---

    /**
     * @notice Parameters for initializing the public sale contract
     * @param saleStartTimestamp Unix timestamp when the sale begins
     * @param saleEndTimestamp Unix timestamp when the sale ends
     * @param owner Address that will own the contract and can call ownerSettle
     * @param saleTokenHolder Address holding the sale tokens to be distributed
     * @param commitmentToken Address of the token users commit (use NATIVE_ASSET constant for ETH)
     * @param saleToken Address of the token being sold
     * @param kycVerifier Address of the KYC verification contract
     * @param saleProceedsReceiver Address that receives sale proceeds
     * @param protocolFeeReceiver Address that receives protocol fees
     * @param minimumCommitment Minimum commitment amount per user
     * @param maximumCommitment Maximum commitment amount per user
     * @param minimumTotalCommitment Minimum total commitments for successful sale
     * @param maximumTotalCommitment Maximum total commitments allowed
     * @param saleTokenPrice Price per sale token in commitment token units (with PRECISION decimals)
     * @param decreaseCommitmentFee Fee percentage for decreasing commitment (with PRECISION decimals)
     * @param protocolFee Fee percentage taken from proceeds (with PRECISION decimals)
     */
    struct InitializerParams {
        uint48 saleStartTimestamp;
        uint48 saleEndTimestamp;
        address owner;
        address saleTokenHolder;
        address commitmentToken;
        address saleToken;
        address kycVerifier;
        address saleProceedsReceiver;
        address protocolFeeReceiver;
        uint256 minimumCommitment;
        uint256 maximumCommitment;
        uint256 minimumTotalCommitment;
        uint256 maximumTotalCommitment;
        uint256 saleTokenPrice;
        uint256 decreaseCommitmentFee;
        uint256 protocolFee;
    }

    // --- Enums ---

    /**
     * @notice Represents the current state of the sale
     * @dev NOT_STARTED: Before saleStartTimestamp
     * @dev ACTIVE: Between start and end timestamps with capacity remaining
     * @dev SUCCEEDED: Reached maximum total commitment OR (sale ended AND reached minimum total commitment)
     * @dev FAILED: Ended without reaching minimum commitment
     */
    enum SaleState {
        NOT_STARTED,
        ACTIVE,
        SUCCEEDED,
        FAILED
    }

    // --- Events ---

    /**
     * @notice Emitted when a user increases their commitment
     * @param account Address of the user
     * @param amount Amount of commitment increase
     */
    event CommitmentIncreased(address indexed account, uint256 amount);

    /**
     * @notice Emitted when a user decreases their commitment
     * @param account Address of the user
     * @param amount Amount of commitment decrease (before fees)
     */
    event CommitmentDecreased(address indexed account, uint256 amount);

    /**
     * @notice Emitted when a user settles after successful sale
     * @param account Address of the user
     * @param recipient Address receiving the sale tokens
     * @param saleTokenAmount Amount of sale tokens received
     */
    event SuccessfulSaleSettled(
        address indexed account,
        address indexed recipient,
        uint256 saleTokenAmount
    );

    /**
     * @notice Emitted when a user settles after failed sale
     * @param account Address of the user
     * @param recipient Address receiving the refunded commitment
     * @param commitmentTokenAmount Amount of commitment tokens refunded
     */
    event FailedSaleSettled(
        address indexed account,
        address indexed recipient,
        uint256 commitmentTokenAmount
    );

    /**
     * @notice Emitted when owner settles after successful sale
     * @param owner Address of the contract owner
     * @param saleProceeds Amount sent to saleProceedsReceiver
     * @param protocolFee Amount sent to protocolFeeReceiver
     */
    event SuccessfulSaleOwnerSettled(
        address indexed owner,
        uint256 saleProceeds,
        uint256 protocolFee
    );

    /**
     * @notice Emitted when owner settles after failed sale
     * @param owner Address of the contract owner
     * @param saleTokenAmount Amount of sale tokens returned
     * @param decreaseCommitmentFees Amount of collected fees returned
     */
    event FailedSaleOwnerSettled(
        address indexed owner,
        uint256 saleTokenAmount,
        uint256 decreaseCommitmentFees
    );

    // --- Initializer Functions ---

    /**
     * @notice Initializes the public sale contract
     * @param params_ Initialization parameters
     */
    function initialize(InitializerParams memory params_) external;

    // --- View Functions ---

    /**
     * @notice Returns the current state of the sale
     * @return state Current sale state
     */
    function saleState() external view returns (SaleState state);

    /**
     * @notice Returns whether the owner has settled
     * @return settled True if owner has settled, false otherwise
     */
    function ownerSettled() external view returns (bool settled);

    /**
     * @notice Returns the sale start timestamp
     * @return timestamp Unix timestamp when sale starts
     */
    function saleStartTimestamp() external view returns (uint48 timestamp);

    /**
     * @notice Returns the sale end timestamp
     * @return timestamp Unix timestamp when sale ends
     */
    function saleEndTimestamp() external view returns (uint48 timestamp);

    /**
     * @notice Returns the commitment token address
     * @return token Address of the token used for commitments (or NATIVE_ASSET for ETH)
     */
    function commitmentToken() external view returns (address token);

    /**
     * @notice Returns the sale token address
     * @return token Address of the token being sold
     */
    function saleToken() external view returns (address token);

    /**
     * @notice Returns the KYC verifier address
     * @return verifier Address of the KYC verification contract
     */
    function kycVerifier() external view returns (address verifier);

    /**
     * @notice Returns the sale proceeds receiver address
     * @return receiver Address that receives sale proceeds
     */
    function saleProceedsReceiver() external view returns (address receiver);

    /**
     * @notice Returns the protocol fee receiver address
     * @return receiver Address that receives protocol fees
     */
    function protocolFeeReceiver() external view returns (address receiver);

    /**
     * @notice Returns the minimum commitment per user
     * @return amount Minimum commitment amount
     */
    function minimumCommitment() external view returns (uint256 amount);

    /**
     * @notice Returns the maximum commitment per user
     * @return amount Maximum commitment amount
     */
    function maximumCommitment() external view returns (uint256 amount);

    /**
     * @notice Returns the minimum total commitment for successful sale
     * @return amount Minimum total commitment amount
     */
    function minimumTotalCommitment() external view returns (uint256 amount);

    /**
     * @notice Returns the maximum total commitment allowed
     * @return amount Maximum total commitment amount
     */
    function maximumTotalCommitment() external view returns (uint256 amount);

    /**
     * @notice Returns the price per sale token
     * @return price Price in commitment token units (with PRECISION decimals)
     */
    function saleTokenPrice() external view returns (uint256 price);

    /**
     * @notice Returns the fee for decreasing commitment
     * @return fee Fee percentage (with PRECISION decimals)
     */
    function decreaseCommitmentFee() external view returns (uint256 fee);

    /**
     * @notice Returns the protocol fee
     * @return fee Fee percentage (with PRECISION decimals)
     */
    function protocolFee() external view returns (uint256 fee);

    /**
     * @notice Returns the total commitments in the sale
     * @return total Total commitment amount
     */
    function totalCommitments() external view returns (uint256 total);

    /**
     * @notice Returns the collected decrease commitment fees
     * @return fees Total fees collected
     */
    function collectedDecreaseCommitmentFees()
        external
        view
        returns (uint256 fees);

    /**
     * @notice Returns a user's commitment amount
     * @param account_ Address to query
     * @return amount Commitment amount
     */
    function commitments(
        address account_
    ) external view returns (uint256 amount);

    /**
     * @notice Returns whether a user has settled
     * @param account_ Address to query
     * @return hasSettled True if settled, false otherwise
     */
    function settled(address account_) external view returns (bool hasSettled);

    // --- State-Changing Functions ---

    /**
     * @notice Increases commitment using native asset (ETH)
     * @param verifyingSignature_ The verifier signature attesting to KYC status
     * @param signatureExpiration_ The expiration timestamp of the signature
     * @dev Reverts if commitment token is not NATIVE_ASSET
     */
    function increaseCommitmentNative(
        bytes calldata verifyingSignature_,
        uint48 signatureExpiration_
    ) external payable;

    /**
     * @notice Increases commitment using ERC20 tokens
     * @param increaseAmount_ Amount to increase commitment by
     * @param verifyingSignature_ The verifier signature attesting to KYC status
     * @param signatureExpiration_ The expiration timestamp of the signature
     * @dev Reverts if commitment token is NATIVE_ASSET
     */
    function increaseCommitmentERC20(
        uint256 increaseAmount_,
        bytes calldata verifyingSignature_,
        uint48 signatureExpiration_
    ) external;

    /**
     * @notice Decreases commitment and sends funds to recipient
     * @param decreaseAmount_ Amount to decrease commitment by
     * @param recipient_ Address to receive the commitment tokens
     * @dev Fee is deducted from the decrease amount
     */
    function decreaseCommitment(
        uint256 decreaseAmount_,
        address recipient_
    ) external;

    /**
     * @notice Settles user's commitment after sale ends
     * @param recipient_ Address to receive tokens (sale tokens if successful, commitment tokens if failed)
     * @dev Can only be called after sale has ended
     */
    function settle(address recipient_) external;

    /**
     * @notice Owner settles the sale proceeds and fees
     * @dev Can only be called by owner after sale has ended
     */
    function ownerSettle() external;
}

